import {patchTypes,patchScopes,patchRoute,selectGamePatches} from './game-patches-model.js?v=e0a55e8f4caa';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=value=>String(value||'').replaceAll('-','.');
const safeURL=value=>{try{const url=new URL(value);return url.protocol==='https:'?url.href:'';}catch{return '';}};
const language={ko:'한국어',en:'영어',ja:'일본어'};
const tag=type=>`<span class="gp-tag" data-kind="${esc(type)}">${esc(patchTypes[type]||type)}</span>`;
function sources(entry){return `<div class="gp-source-links">${entry.sources.map(source=>{const url=safeURL(source.url);return url?`<a class="btn small" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(source.official===false?'보조 기록':'공식 원문')} · ${esc(language[source.language]||source.language)} ↗</a>`:'';}).join('')}</div>`;}
function people(entry,characters){return `<div class="gp-people">${entry.characterIds.map(id=>characters[id]).filter(Boolean).map(c=>`<a href="${patchRoute({c:c.id,scope:entry.scope})}"><img src="${esc(c.portrait)}" alt="" width="24" height="24" loading="lazy"><span>${esc(c.name)}</span></a>`).join('')}</div>`;}
function coverage(catalog){
 const meta=catalog.meta;
 return `<details class="gp-coverage"><summary>수집 범위와 자료 기준</summary><div><p>${esc(meta.coverageText)}</p><p>자료 확인 ${date(meta.checkedAt)} · ${Number(meta.sourceCount).toLocaleString('ko-KR')}개 원문 대조</p><ul>${(meta.limitations||[]).map(text=>`<li>${esc(text)}</li>`).join('')}</ul><div class="gp-year-coverage">${(meta.years||[]).map(y=>`<span><strong>${esc(y.year)}</strong> ${Number(y.count)}건</span>`).join('')}</div></div></details>`;
}
function noteHTML(entry,characters,filters){
 return `<article class="gp-detail"><a class="back-link" href="${patchRoute(filters)}">← 패치 목록으로</a><div class="gp-detail-top"><span class="gp-server ${entry.scope==='test'?'is-test':''}">${esc(patchScopes[entry.scope]||entry.scope)}</span><span>${entry.dateStatus==='confirmed'?'적용일':'적용일 확인 필요 · 공지 기준'} <time datetime="${esc(entry.date)}">${date(entry.date)}</time></span></div><h2>${esc(entry.title)}</h2><div class="gp-tags">${entry.types.map(tag).join('')}</div>${entry.dateNote?`<p class="note">${esc(entry.dateNote)}</p>`:''}<div class="gp-detail-summary"><h3>주요 항목 안내</h3><ul>${entry.summary.map(text=>`<li>${esc(text)}</li>`).join('')}</ul></div>${entry.highlights?.length?`<section class="gp-changes"><h3>검토한 캐릭터 변경 요약</h3>${entry.highlights.map(change=>`<div>${tag(change.type)}<p>${esc(change.text)}</p></div>`).join('')}</section>`:''}${entry.characterIds.length?`<section><h3>관련 캐릭터</h3>${people(entry,characters)}</section>`:''}<p class="gp-reading-note">한국어 요약과 캐릭터 연결을 제공하는 기록입니다. 세부 조건·전체 항목은 공식 원문에서 확인하세요. 공지에 함께 실린 다음 업데이트 예고는 적용된 변경으로 취급하지 않습니다.</p>${sources(entry)}<details class="gp-original-titles"><summary>원문 제목과 공지 표기일</summary>${entry.sources.map(source=>`<p><strong>${esc(language[source.language]||source.language)}</strong> · ${esc(source.title)}<br><small>공지 표기일 ${date(source.noticeDate)}${source.official===false?' · 공식 원문 미확보':''}</small></p>`).join('')}</details></article>`;
}
function card(entry,characters,filters){
 const highlight=filters.c?entry.highlights?.find(change=>change.characterId===filters.c):null;
 const blurb=highlight?.text||(filters.c?`${characters[filters.c].name} 관련 ${entry.characterChanges[filters.c].map(type=>patchTypes[type]).join(' · ')} 항목이 있습니다.`:entry.summary[0]);
 return `<article class="gp-record"><div class="gp-record-date"><time datetime="${esc(entry.date)}">${date(entry.date)}</time><span>${entry.dateStatus==='confirmed'?'적용일':'공지 기준'}</span></div><div class="gp-record-body"><div class="gp-tags">${entry.scope==='test'?'<span class="gp-server is-test">테스트 서버</span>':''}${entry.types.slice(0,4).map(tag).join('')}${entry.dateStatus!=='confirmed'?'<span class="gp-tag">날짜 확인 필요</span>':''}</div><h3><a href="${patchRoute({...filters,note:entry.id})}">${esc(entry.title)}</a></h3><p>${esc(blurb||'공식 공지의 전체 내용을 확인하세요.')}</p>${entry.characterIds.length?`<div class="gp-character-names">${entry.characterIds.slice(0,7).map(id=>esc(characters[id]?.name||'')).join(' · ')}${entry.characterIds.length>7?` 외 ${entry.characterIds.length-7}명`:''}</div>`:''}<a class="text-link" href="${patchRoute({...filters,note:entry.id})}">변경 항목·공식 원문 보기 →</a></div></article>`;
}
export function gamePatchesHTML(catalog,characters,params={}){
 const selection=selectGamePatches(catalog,characters,params),{filters,years,entries,matches,page,pages,note}=selection;
 const select=(name,values,label)=>`<label class="gp-filter${name==='scope'?' gp-wide-filter':''}"><span>${label}</span><select name="${name}" class="filter-select">${values.map(([value,text])=>`<option value="${esc(value)}" ${filters[name]===value?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`;
 const count=catalog.entries.filter(entry=>entry.scope==='live').length;
 return `<div class="game-patches-page"><section class="gp-heading"><div><div class="eyebrow">IDENTITY V · PATCH ARCHIVE</div><h1>게임 패치노트</h1><p>장원의 변화가 쌓인 기록.<br>캐릭터와 날짜로, 필요한 업데이트를 찾으세요.</p></div><div class="gp-archive-stats"><strong>${count.toLocaleString('ko-KR')}<small>정식 서버 기록</small></strong><span>${date(catalog.meta.startDate)} — ${date(catalog.meta.latestDate)}</span><small>원문 연결 · 한국어 요약</small></div></section>${coverage(catalog)}
 <form class="gp-filter-form" data-gp-form><div class="gp-filter-top"><label class="gp-search"><span>내용 검색</span><input type="search" name="q" value="${esc(filters.q)}" placeholder="캐릭터 · 변경 내용 · 날짜" autocomplete="off" maxlength="120"></label>${select('c',[['','모든 캐릭터'],...Object.values(characters).sort((a,b)=>a.name.localeCompare(b.name,'ko')).map(c=>[c.id,c.name])],'캐릭터')}</div><div class="gp-filter-bottom">${select('year',[['','전체 연도'],...years.map(year=>[year,year+'년'])],'연도')}${select('type',[['','모든 변경'],['gameplay','전투 조정·오류 수정'],...Object.entries(patchTypes)],'변경 유형')}${select('scope',Object.entries(patchScopes),'서버')}<label class="gp-filter gp-wide-filter"><span>마지막 플레이 날짜 이후</span><input type="date" name="since" value="${esc(filters.since)}" max="${esc(catalog.meta.checkedAt)}"></label><button class="btn primary" type="submit">기록 찾기</button><a class="btn quiet" href="${patchRoute()}">초기화</a></div></form>
 ${filters.scope==='test'?'<p class="note gp-filter-note">테스트 서버 기록입니다. 정식 서버의 현재 성능이나 캐릭터 카드의 최근 변경에는 합산하지 않습니다.</p>':''}${filters.since?`<p class="gp-filter-note">${date(filters.since)} 이후 적용일이 확인된 변경을 보여드립니다.${filters.c?' 선택한 캐릭터의 복귀 후 변경을 살펴보세요.':''}</p>`:''}${selection.invalid?'<p class="note" role="status">캐릭터 또는 날짜 조건을 확인할 수 없습니다. 조건을 다시 선택해 주세요.</p>':''}
 ${note?noteHTML(note,characters,{...filters,page}):selection.missingNote?'<div class="empty"><h2>이 패치 기록을 찾지 못했습니다.</h2><p>목록에서 확인할 기록을 선택해 주세요.</p></div>':`<section aria-labelledby="gp-results-title"><div class="gp-results-heading"><h2 id="gp-results-title" tabindex="-1">${filters.c?esc(characters[filters.c].name)+'의 관련 기록':'업데이트 기록'}</h2><span role="status">${matches.length.toLocaleString('ko-KR')}건 · ${page} / ${pages}페이지</span></div><div class="gp-records">${entries.length?entries.map(entry=>card(entry,characters,{...filters,page})).join(''):'<div class="empty"><h3>조건에 맞는 기록이 없습니다.</h3><p>검색어·기간·변경 유형을 조정해 보세요. 검색 결과가 없다는 사실이 패치가 없었다는 뜻은 아닙니다.</p></div>'}</div>${pages>1?`<nav class="gp-pagination" aria-label="패치 기록 페이지">${page>1?`<a class="btn" href="${patchRoute({...filters,page:page-1})}">← 이전</a>`:'<span></span>'}<span>${page} / ${pages}</span>${page<pages?`<a class="btn" href="${patchRoute({...filters,page:page+1})}">다음 →</a>`:'<span></span>'}</nav>`:''}</section>`}</div>`;
}
export function mountGamePatches(root,{catalog,characters,params={},navigate}){
 root.innerHTML=gamePatchesHTML(catalog,characters,params);
 function submit(event){if(!event.target.matches('[data-gp-form]'))return;event.preventDefault();const p={v:'gamepatches'};for(const key of ['q','c','year','type','scope','since']){const value=event.target.elements.namedItem(key)?.value?.trim();if(value)p[key]=value;}navigate(p);}
 root.addEventListener('submit',submit);
 return ()=>root.removeEventListener('submit',submit);
}
